INSERT INTO `v1_900885b0bfc09c39a2b99ea981c7f02b5934db6f5f3d8dbff9b9d396cf4d00b5` VALUES (1201820011, 0, "vo_travel_talk_20018_02", 20182, "", "", "vo_travel_talk", 21, "", "", 0);
INSERT INTO `v1_900885b0bfc09c39a2b99ea981c7f02b5934db6f5f3d8dbff9b9d396cf4d00b5` VALUES (1201820012, 1, "……それに、手ぶらで帰ったとなると\n秘書にまた小言を言われそうですし。\nあの子がグゥの音も出なくなるくらい\n稼いで稼いで稼ぎますわよ～っ！", 20182, 0, 1, 118011, 11, 0, 0, 10);
INSERT INTO `v1_900885b0bfc09c39a2b99ea981c7f02b5934db6f5f3d8dbff9b9d396cf4d00b5` VALUES (1201820013, "", "", 20182, "", "", 0, 91, "", "", "");
